def greet(name: str) -> str:
    if name is None:
        raise ValueError("Name cannot be None")
    stripped_name = name.strip()
    if not stripped_name:
        raise ValueError("Name cannot be empty or whitespace only")
    return f"Hello, {stripped_name}!"

